"""Generate the Lean data from the published JSON. Lean checks every selected block."""
import json
from pathlib import Path

from verify import CUTOFF, template


def main():
    root = Path(__file__).resolve().parent
    data = json.loads((root / "certificate.json").read_text(encoding="utf-8"))
    extra = json.loads((root / "cyclic.json").read_text(encoding="utf-8"))
    sets = {**extra, **data["short_sets"]}
    out = [
        "-- Generated by generate_blocks.py from certificate.json and cyclic.json.",
        "import Std", "", "namespace DihedralCert", "",
        "inductive Block where",
        "  | direct (A B : List Int)",
        "  | lift (hi m g r w : Nat) (U V S : List Int)", "",
    ]
    for q, s in sorted(sets.items(), key=lambda pair: int(pair[0])):
        out.append(f"private def s{q} : List Int := {s}")
    intervals = []
    for k, q in data["lifts"]:
        u, v = template(k)
        r = k - 2 if k <= 6 else 2 * (k - 4)
        w = 2*r - (1 if k <= 6 else 3)
        m = q*q + q + 1
        g = m - 1 - max(sets[str(q)]) if str(q) in data["short_sets"] else q
        lo = (11*(k*(q+1))**2 + 63)//64
        hi = min(CUTOFF-1, w*m + 2*g + 1)
        intervals.append((lo, hi, f".lift {hi} {m} {g} {r} {w} {u} {v} s{q}"))
    for row in data["small"]:
        intervals.append((row["n"], row["n"], f".direct {row['A']} {row['B']}"))
    for row in data["direct"]:
        for n in row["n"]:
            a = list(range(row["a"]))
            b = sorted({x % n for x in row["B"]})
            intervals.append((n, n, f".direct {a} {b}"))
    n = 1
    blocks = []
    while n < CUTOFF:
        _, hi, entry = max((i for i in intervals if i[0] <= n <= i[1]),
                           key=lambda i: i[1])
        blocks.append(f"  {entry}")
        n = hi + 1
    out += ["", "def certificateBlocks : List Block := [", ",\n".join(blocks),
            "]", "", "end DihedralCert", ""]
    (root / "Dihedral" / "Blocks.lean").write_text("\n".join(out), encoding="utf-8")


if __name__ == "__main__":
    main()
